"""Frozen copy of the v1 ``MessageCodec`` (das-observability-operations, Req 7.2, 19.7).

Phase 2 changes ``das.codec`` (Envelope_V2, ``trace_context``, new message types).
Byte-identity properties compare the new codec against *this* reference, so it must
not track those changes: the envelope field set, the supported message types and
versions, and the canonical JSON rules are all copied here instead of imported.

Only the typed Message / payload classes are reused, because v1 payloads are not
changed by Phase 2 and ``decode`` must hand back objects comparable with the ones
the system under test produces.

Do not edit this file to follow ``das.codec``; it records v1 behavior.
"""

from __future__ import annotations

import json
from datetime import datetime
from typing import Any, Final

from pydantic import ValidationError

from das.codec.envelope import (
    ControlMessage,
    HeartbeatMessage,
    JobDispatchMessage,
    JobResultMessage,
)
from das.models.base import to_utc_ms
from das.models.results import (
    ControlPayload,
    HeartbeatPayload,
    JobDispatchPayload,
    JobResultPayload,
)

V1_MAX_BYTES: Final = 1_048_576
V1_MAX_MESSAGE_ID_LENGTH: Final = 64
V1_SUPPORTED_VERSIONS: Final = frozenset({1})
V1_ENVELOPE_FIELDS: Final = frozenset(
    {"type", "schema_version", "message_id", "correlation_id", "timestamp", "payload"}
)
V1_MESSAGE_CLASSES: Final[dict[str, type]] = {
    "job_dispatch": JobDispatchMessage,
    "job_result": JobResultMessage,
    "heartbeat": HeartbeatMessage,
    "control": ControlMessage,
}
V1_PAYLOAD_MODELS: Final[dict[str, type]] = {
    "job_dispatch": JobDispatchPayload,
    "job_result": JobResultPayload,
    "heartbeat": HeartbeatPayload,
    "control": ControlPayload,
}
_V1_TYPED_CLASSES: Final = tuple(V1_MESSAGE_CLASSES.values())


class V1ParseError(ValueError):
    """Bytes the v1 codec would reject (mirrors v1 ``ParseError``)."""

    def __init__(self, reason: str, field: str = "$") -> None:
        self.reason = reason
        self.field = field
        super().__init__(f"{field}: {reason}")


class V1EncodeError(ValueError):
    """A Message the v1 codec cannot serialize (too large, or not representable in v1)."""


def _reject_constant(name: str) -> Any:
    raise ValueError(f"non-standard JSON constant {name}")


def _no_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    obj: dict[str, Any] = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError(f"duplicate key {key!r}")
        obj[key] = value
    return obj


class V1ReferenceCodec:
    """Encode/decode exactly as DAS v1 did."""

    def __init__(self, max_bytes: int = V1_MAX_BYTES) -> None:
        self.max_bytes = max_bytes

    def encode(self, message: object) -> bytes:
        """Canonical v1 bytes: sorted keys, compact separators, ``ensure_ascii=False``.

        Only the six v1 envelope fields are serialized. A Message carrying a field v1
        never had (e.g. a non-null ``trace_context``) is not representable in v1 and
        raises :class:`V1EncodeError` rather than being silently dropped.
        """
        if not isinstance(message, _V1_TYPED_CLASSES):
            raise TypeError(f"not a v1 Message: {type(message).__name__}")
        dumped: dict[str, Any] = message.model_dump(mode="json")  # type: ignore[attr-defined]
        extra = {k for k, v in dumped.items() if k not in V1_ENVELOPE_FIELDS and v is not None}
        if extra:
            raise V1EncodeError(f"fields not representable in v1: {sorted(extra)}")
        envelope = {k: dumped[k] for k in V1_ENVELOPE_FIELDS}
        try:
            data = json.dumps(
                envelope,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
                allow_nan=False,
            ).encode("utf-8")
        except (UnicodeEncodeError, ValueError) as exc:
            raise V1EncodeError(f"message cannot be serialized: {exc}") from exc
        if len(data) > self.max_bytes:
            raise V1EncodeError(f"message size {len(data)} exceeds {self.max_bytes}")
        return data

    def decode(self, data: bytes | bytearray | memoryview) -> object:
        """Parse bytes with the v1 rules (exact six-field envelope, ``schema_version`` 1)."""
        if not isinstance(data, bytes | bytearray | memoryview):
            raise V1ParseError(f"expected bytes, got {type(data).__name__}")
        raw = bytes(data)
        if len(raw) > self.max_bytes:
            raise V1ParseError(f"message size {len(raw)} exceeds {self.max_bytes}")
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise V1ParseError(f"invalid UTF-8: {exc.reason}") from None
        try:
            obj = json.loads(
                text, parse_constant=_reject_constant, object_pairs_hook=_no_duplicate_keys
            )
        except (ValueError, RecursionError) as exc:
            raise V1ParseError(f"invalid JSON: {exc}") from None
        if not isinstance(obj, dict):
            raise V1ParseError("envelope must be a JSON object")
        missing = V1_ENVELOPE_FIELDS - obj.keys()
        if missing:
            raise V1ParseError("missing required envelope field", min(missing))
        extra = obj.keys() - V1_ENVELOPE_FIELDS
        if extra:
            raise V1ParseError("unknown envelope field", min(extra))
        msg_type = obj["type"]
        if not isinstance(msg_type, str) or msg_type not in V1_MESSAGE_CLASSES:
            raise V1ParseError(f"unrecognized message type {msg_type!r}", "type")
        version = obj["schema_version"]
        if isinstance(version, bool) or not isinstance(version, int) or version < 1:
            raise V1ParseError("schema_version must be a positive integer", "schema_version")
        if version not in V1_SUPPORTED_VERSIONS:
            raise V1ParseError(f"unsupported schema_version {version}", "schema_version")
        message_id = obj["message_id"]
        if not isinstance(message_id, str) or not 1 <= len(message_id) <= V1_MAX_MESSAGE_ID_LENGTH:
            raise V1ParseError("message_id must be a string of 1 to 64 characters", "message_id")
        correlation_id = obj["correlation_id"]
        if not isinstance(correlation_id, str):
            raise V1ParseError("correlation_id must be a string", "correlation_id")
        timestamp = self._parse_timestamp(obj["timestamp"])
        payload_raw = obj["payload"]
        if not isinstance(payload_raw, dict):
            raise V1ParseError("payload must be a JSON object", "payload")
        try:
            payload = V1_PAYLOAD_MODELS[msg_type].model_validate(payload_raw, strict=True)
        except ValidationError as exc:
            err = exc.errors()[0]
            path = ".".join(["payload", *(str(p) for p in err["loc"])])
            raise V1ParseError(f"payload does not match the {msg_type} schema", path) from None
        return V1_MESSAGE_CLASSES[msg_type](
            schema_version=version,
            message_id=message_id,
            correlation_id=correlation_id,
            timestamp=timestamp,
            payload=payload,
        )

    @staticmethod
    def _parse_timestamp(value: object) -> datetime:
        if not isinstance(value, str):
            raise V1ParseError("timestamp must be an ISO 8601 string", "timestamp")
        try:
            return to_utc_ms(datetime.fromisoformat(value))
        except ValueError as exc:
            raise V1ParseError(f"invalid timestamp: {exc}", "timestamp") from None


__all__ = [
    "V1_ENVELOPE_FIELDS",
    "V1_MAX_BYTES",
    "V1EncodeError",
    "V1ParseError",
    "V1ReferenceCodec",
]
